with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '桃鳩図', '徽宗', 'https://upload.wikimedia.org/wikipedia/commons/5/5b/Momohatozu_Huizong.JPG', '北宋の第8代皇帝・徽宗の筆と伝わる小さな花鳥画です。縦28.5cm、横26.1cmの絹に、桃の枝にとまる一羽の鳩を、輪郭線をほとんど使わない没骨という描き方で表しています。右上には徽宗独特の書体「痩金体」で「大観丁亥御筆」と書かれ、これに従えば1107年、徽宗26歳の作になります。足利義満の印が押され、のちに井上馨が所蔵しました。真筆かどうかには議論もありますが、院体画の傑作として日本の国宝に指定されています（個人蔵）。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Momohatozu_Huizong.JPG'),
    (2, '灰色と黒のアレンジメント-母の肖像', 'ジェームズ・マクニール・ホイッスラー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Whistlers_Mother_high_res.jpg/960px-Whistlers_Mother_high_res.jpg', 'アメリカ出身でロンドンを拠点にしたホイッスラーが、1871年に母アンナを描いた作品です。灰色の壁の前で横向きに座る黒衣の母を、抑えた色だけで静かにまとめています。画家はこれを肖像画である前に色と形の「アレンジメント（配置）」と考え、題にもそう付けました。1872年にロンドンのロイヤル・アカデミーで展示され、1891年にフランス政府が買い上げました。現在はパリのオルセー美術館が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Whistlers_Mother_high_res.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('辰野登恵子展、長野県立美術館で2027年1月から', '戦後日本の抽象絵画を代表する辰野登恵子の、出身地・長野県で初の大規模回顧展が開かれる。', '長野県立美術館で、リニューアル・オープン5周年記念展として「辰野登恵子 多次元の絵画」が開かれる。会期は2027年1月16日から3月22日まで。戦後日本の抽象絵画を代表する作家のひとり、辰野登恵子（1950〜2014）の出身地・長野県で初の大規模回顧展となる。約40年にわたる画業を、110点を超える絵画や版画、ドローイング、当時の資料とともにたどる。辰野は長野県岡谷市生まれで、1994年に第22回サンパウロ・ビエンナーレの日本代表に選ばれ、翌年には東京国立近代美術館で当時史上最年少となる個展を開いた。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33355',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('アート・バーゼル香港2027、232軒が参加', '2027年3月に開かれるアート・バーゼル香港の概要が発表され、日本からは20軒のギャラリーが出展する。', 'アート・バーゼル香港が、2027年の開催概要と参加ギャラリーを発表した。会期は2027年3月25日から27日まで（プレビューは23日と24日）で、会場は香港コンベンション＆エキシビションセンター。40以上の国と地域から232軒のギャラリーが参加し、そのうち31軒が初参加となる。参加ギャラリーの半数以上はアジア太平洋地域に拠点を置き、日本からはタカ・イシイギャラリーや小山登美夫ギャラリーなど20軒が出展する。メインセクター「Galleries」には171軒が参加する。会場のレイアウトも新しくする。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/market/33375',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('東博で特別展「源氏物語 王朝のかがやき」', '東京国立博物館で2027年1月19日から、東京で初めての「源氏物語展」となる大規模な展覧会が開かれる。', '東京国立博物館で、特別展「源氏物語 王朝のかがやき」が2027年1月19日から3月14日まで開かれる。『源氏物語』をめぐる写本や絵画、工芸品などを集め、東京では初めての「源氏物語展」となる大規模な展覧会。8つの章で構成し、古写本や注釈書、物語を描いた絵画に加え、『源氏物語』を題材とした工芸品や能、浮世絵にも目を向ける。『源氏物語』を描いた現存最古の作品である国宝「源氏物語絵巻」も紹介される。最後の章では、松岡映丘筆「宇治の宮の姫君たち」と上村松園筆「焔」の近代の源氏絵2点で締めくくる。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261123-AEJ3047757/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('岡田敦「幻の馬」展、東京都写真美術館で', 'ユルリ島の馬を15年撮り続けた写真家・岡田敦の展覧会が12月1日から東京都写真美術館で開かれる。', '東京都写真美術館で、「岡田敦｜幻の馬 Yururi Island 1950-2026」が12月1日から開かれる。北海道根室半島の沖合にあるユルリ島で、2011年から15年にわたって続けてきた撮影の集大成となる展覧会で、約80点の作品で構成される。ユルリ島には1950年から昆布漁の労働力として馬が移入されたが、人が島を離れたあとは馬だけが残された。撮影開始時に十数頭いた馬は2026年4月には2頭に減っており、本展ではその2頭を新たに捉えた未発表の新作も公開される。東京の美術館で開く初の大規模展となる。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261119-AEJ3044502/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('静嘉堂文庫美術館で「THE MASKS」展', '仮面と、それに魅せられ集め写し取った人々を紹介する展覧会が静嘉堂文庫美術館で始まった。', '東京・丸の内の静嘉堂文庫美術館で、「THE MASKS 仮面に魅せられた人々」が2026年11月21日から2027年1月17日まで開かれている。人や鬼神の顔をかたどった仮面と、近世から近代にかけて古い仮面を集め、写し取った人々に焦点をあてる。「北海道」の名付け親として知られる松浦武四郎の旧蔵品や、新発田藩主・溝口家に伝わった能面群などを紹介する。明治から大正期の彫刻家・加納鉄哉による伎楽面や追儺面の模作も並ぶ。前期は12月20日まで、後期は12月22日から。', '', '展覧会', 'https://www.museum.or.jp/news/127831',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('窓外の化粧', 'Make-up outside the Window', '古賀春江', 'Harue Koga',
        1930,
        (select slug from public.art_movements where slug = 'surrealism'),
        '神奈川県立近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Koga_Harue_-_Make-up_outside_the_Window.jpg/960px-Koga_Harue_-_Make-up_outside_the_Window.jpg', '1930年の二科展に出品された、古賀春江のシュルレアリスム期を代表する作品の一つです。画面右上では、高層ビルの上で女性が踊っています。この部分は雑誌「アサヒグラフ」1925年の写真「エッフェル塔上ダンスの一幕」から着想されたことが、残されたスケッチからわかっています。雑誌の写真を組み合わせて画面を作る方法は、マックス・エルンストのコラージュと同じ手法です。一方で古賀は夢や無意識を描くことには否定的で、近代的な建築や機械を明快に配置しました。ヨーロッパのシュルレアリスムを受け止めつつ、構成を重んじる日本独自の超現実主義へ読み替えた一枚です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Koga_Harue_-_Make-up_outside_the_Window.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('星光寺縁起絵巻', 'Seikō-ji Engi Emaki', '土佐光信', 'Tosa Mitsunobu',
        1487,
        (select slug from public.art_movements where slug = 'yamato-e'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Seikoji_engi_emaki_-_scroll_1_p2_-_detail.jpg/960px-Seikoji_engi_emaki_-_scroll_1_p2_-_detail.jpg', '京都・六角大宮の星光寺の本尊、地蔵菩薩の由来と霊験を描いた2巻の絵巻です。絵は土佐光信、詞書は三条西実隆の筆で、1487年の作として重要文化財に指定されています。前半では山城守・平典親がお告げを受けて茨の中から地蔵像を見つけ、寺を建てます。後半では、嵐で屋根が飛んだ尼寺を、若い僧に姿を変えた地蔵が直します。典親の屋敷の襖や屏風には中国風の水墨画が描かれ、当時の好みもうかがえます。平安以来の絵巻の伝統を受け継ぎ、宮廷の絵所預として土佐派を立て直した光信の、明快な画風を伝える作品です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Seikoji_engi_emaki_-_scroll_1_p2_-_detail.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('読書する娘', 'A Young Girl Reading', 'ジャン・オノレ・フラゴナール', 'Jean-Honoré Fragonard',
        1769,
        (select slug from public.art_movements where slug = 'rococo'),
        'ワシントン・ナショナル・ギャラリー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Fragonard%2C_The_Reader.jpg/960px-Fragonard%2C_The_Reader.jpg', '窓辺のクッションにもたれ、右手の小さな本を読みふける若い女性を横から描いた作品です。黄色のドレスや襟元のリボンは勢いのある速い筆づかいで描かれ、乾く前の白い絵具を筆の尻で引っかいて線を作るなど、大胆な技法が見られます。X線などの調査で、下にはこちらを向いた別の女性の顔が描かれていたことがわかり、「空想的人物」と呼ばれる肖像の連作の一点を描き直したものと考えられています。ロココらしい軽やかで素早い筆さばきを生かしながら、恋の戯れではなく、読書に没頭する静かなひとときを主題にした点が見どころです。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Fragonard,_The_Reader.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('我が子を食らうサトゥルヌス', 'Saturn Devouring His Son', 'フランシスコ・デ・ゴヤ', 'Francisco Goya',
        1820,
        (select slug from public.art_movements where slug = 'romanticism'),
        'プラド美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Francisco_de_Goya%2C_Saturno_devorando_a_su_hijo_%281819-1823%29.jpg/960px-Francisco_de_Goya%2C_Saturno_devorando_a_su_hijo_%281819-1823%29.jpg', '晩年のゴヤが、マドリードのマンサナーレス川近くに買った家（のちの「聾者の家」）の食堂の壁に、黒と褐色の絵具で描いた「黒い絵」の一点です。ローマ神話の神サトゥルヌスが、子に滅ぼされるという予言を恐れてわが子を食らう瞬間を、闇の中に大きく浮かび上がらせています。ルーベンスの同じ主題の作品を思わせますが、ゴヤは神話の枠を超え、人間の狂気そのものを突きつけました。壁画はのちにキャンバスに移され、現在はプラド美術館にあります。理性より内面の闇を描くロマン主義を極限まで押し進め、その激しい表現は後の表現主義を思わせると評されます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Francisco_de_Goya,_Saturno_devorando_a_su_hijo_(1819-1823).jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('古賀春江', 'Harue Koga', '古賀春江',
        1895, 1933, 'japan', array['surrealism']::text[],
        '日本の初期シュルレアリスムを代表する、大正から昭和初期の洋画家です。', '1895年、福岡県久留米市の寺の住職の長男として生まれました。本名は亀雄です。久留米で洋画家の松田実に絵を習い、1912年に中学を退学して上京し、太平洋画会研究所や日本水彩画会研究所で学びました。1915年に僧籍に入り、春江を呼び名としました。

1922年、二科展に出した「埋葬」が二科賞を受けます。セザンヌや未来派、とくにパウル・クレーの影響を受けて作風を次々に変え、1929年の「海」で、雑誌の写真や図版を組み合わせた構成的な画面にたどり着きました。「海」は発表当時、日本の絵画にシュルレアリスムが初めて現れたものとみなされました。

古賀は夢や無意識を描くことには否定的で、超現実主義を「主智主義」ととらえ、近代的な建築や機械を明快に配置しました。代表作に「海」（東京国立近代美術館）や「窓外の化粧」（神奈川県立近代美術館）があります。川端康成とも親交を結びましたが、病のため1933年に38歳で亡くなりました。', 'https://ja.wikipedia.org/wiki/%E5%8F%A4%E8%B3%80%E6%98%A5%E6%B1%9F')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('原田直次郎', 'Harada Naojirō', '原田直次郎',
        1863, 1899, 'japan', array['yoga-meiji']::text[],
        'ドイツで学んだ堅実な写実で、明治中期の洋画を支えた画家です。', '1863年、江戸小石川に兵学者・原田一道の次男として生まれました。東京外国語学校でフランス語を学んだのち、高橋由一に洋画を学び、1884年にドイツへ渡ってミュンヘンで画家ガブリエル・フォン・マックスに師事しました。留学中に森鷗外と親しくなり、鷗外の小説『うたかたの記』の主人公のモデルにもなっています。

1887年に帰国すると、国内は洋画排斥の空気の中にあり、東京美術学校も洋画科を置かずに設立されました。原田は自宅に画塾「鐘美舘」を開いて謝金を取らずに後進を教え、明治美術会で洋画の地位を高めようと努めました。1890年の内国勧業博覧会に出した歴史画の大作「騎竜観音」は、人々の注目を集めました。

1893年ごろから病に倒れ、寝たまま制作を続けましたが、1899年に36歳で亡くなりました。「騎竜観音」と「靴屋の親爺」は重要文化財に指定されています。黒田清輝らの明るい外光表現が広まると、原田ら古参の暗い画風は「旧派」と呼ばれるようになりました。', 'https://ja.wikipedia.org/wiki/%E5%8E%9F%E7%94%B0%E7%9B%B4%E6%AC%A1%E9%83%8E')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フォード・マドックス・ブラウン', 'Ford Madox Brown', 'マドックス・ブラウン',
        1821, 1893, 'west', array['pre-raphaelite']::text[],
        'ラファエル前派と深く交わり、社会を見つめる鋭い目を持った19世紀イギリスの画家です。', '1821年、フランスのカレーに生まれました。父は退役した海軍士官でした。1835年に家族でベルギーのブルッヘに移って絵を学び、ヘントを経て、1837年からアントウェルペン王立芸術学院でフスタフ・ワッペルスに師事しました。1840年にはロンドンのロイヤル・アカデミーの展覧会に初めて出品しています。

ラファエル前派の画家たちと交流し、とくにダンテ・ゲイブリエル・ロセッティと親しくしましたが、正式なメンバーにはなりませんでした。風刺画家ホガースの精神を、ラファエル前派の絵画スタイルで受け継いだと評されます。1861年にはウィリアム・モリスの会社「モリス、マーシャル、フォークナー商会」にも加わりました。

代表作「イギリスの見納め」は、遠ざかる祖国を見つめる移民の夫婦を、画家自身と妻をモデルに描いたものです。「労働」（1852〜1865年）では、ロンドンの道路工事を中心にヴィクトリア朝のあらゆる階級を一枚に描きました。晩年にはマンチェスター市庁舎の大広間に、町の歴史を描いた12枚の壁画を残し、1893年に亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A9%E3%83%BC%E3%83%89%E3%83%BB%E3%83%9E%E3%83%89%E3%83%83%E3%82%AF%E3%82%B9%E3%83%BB%E3%83%96%E3%83%A9%E3%82%A6%E3%83%B3')
